const CHECK_ALPHABET = "ACDEFGHJKLMNPQRSTUVWXYZ";
const CODE_RE = /^V(\d{2})-([A-Z]+)-(\d{3})-([A-Z])$/;

/** Convert a row number (>= 1) to a bijective base-26 label (1 -> A, 27 -> AA). */
function rowToLabel(row) {
	let label = "";
	while (row > 0) {
		row -= 1;
		label = String.fromCharCode(65 + (row % 26)) + label;
		row = Math.floor(row / 26);
	}
	return label;
}

/** Convert a bijective base-26 label to a row number (A -> 1, AA -> 27). */
function labelToRow(label) {
	let row = 0;
	for (const ch of label) row = row * 26 + (ch.charCodeAt(0) - 64);
	return row;
}

/** Check letter for the text before the last dash. */
function checkLetter(text) {
	let sum = 0;
	for (let i = 0; i < text.length; i++) sum += text.charCodeAt(i);
	return CHECK_ALPHABET[sum % 23];
}

/** @param {{ venue: number, row: number, seat: number }} ticket @returns {string} */
export function encodeTicket(ticket) {
	const { venue, row, seat } = ticket;
	for (const [value, min, max] of [
		[venue, 1, 99],
		[row, 1, Infinity],
		[seat, 1, 999],
	]) {
		if (!Number.isInteger(value) || value < min || value > max) {
			throw new RangeError(
				`invalid ticket field: ${String(value)} (expected integer in [${min}, ${max === Infinity ? "∞" : max}])`
			);
		}
	}
	const base = `V${String(venue).padStart(2, "0")}-${rowToLabel(row)}-${String(seat).padStart(3, "0")}`;
	return `${base}-${checkLetter(base)}`;
}

/** @param {string} code @returns {{ venue: number, row: number, seat: number }} */
export function decodeTicket(code) {
	if (typeof code !== "string" || !CODE_RE.test(code)) {
		throw new SyntaxError(`malformed ticket code: ${String(code)}`);
	}
	const [, venueStr, rowLabel, seatStr, check] = code.match(CODE_RE);
	const venue = Number(venueStr);
	const seat = Number(seatStr);
	if (venue < 1 || seat < 1) {
		throw new RangeError(`out-of-range ticket code: ${code}`);
	}
	const base = code.slice(0, -2);
	if (checkLetter(base) !== check) {
		throw new RangeError(`bad check letter in ticket code: ${code}`);
	}
	return { venue, row: labelToRow(rowLabel), seat };
}

