import("./src/ticket-code.js").then(({ encodeTicket, decodeTicket }) => {
  const eq = (a, b, msg) => { if (a !== b) throw new Error(msg + ": " + a + " !== " + b); };
  // R3 row labels
  for (const [row, label] of [[1,"A"],[26,"Z"],[27,"AA"],[52,"AZ"],[53,"BA"],[702,"ZZ"],[703,"AAA"]])
    eq(encodeTicket({ venue: 5, row, seat: 10 }).slice(4, 4+label.length+1), label + "-", "row " + row);
  // R4 examples
  eq(encodeTicket({ venue: 7, row: 28, seat: 12 }), "V07-AB-012-G", "check1");
  eq(encodeTicket({ venue: 1, row: 1, seat: 1 }), "V01-A-001-A", "check2");
  // R5 round-trip
  for (const row of [1, 26, 27, 52, 702, 703, 123456])
    for (const v of [1, 99]) for (const s of [1, 999]) {
      const c = encodeTicket({ venue: v, row, seat: s });
      const d = decodeTicket(c);
      if (d.venue !== v || d.row !== row || d.seat !== s) throw new Error("roundtrip fail " + c + " " + JSON.stringify(d));
    }
  // R1 invalid inputs
  for (const bad of [{venue:0,row:1,seat:1},{venue:100,row:1,seat:1},{venue:1.5,row:1,seat:1},{venue:"7",row:1,seat:1},{venue:1,row:0,seat:1},{venue:1,row:2.5,seat:1},{venue:1,row:1,seat:0},{venue:1,row:1,seat:1000},{venue:1,row:1,seat:"1"},{}])
    try { encodeTicket(bad); throw new Error("no throw for " + JSON.stringify(bad)); } catch (e) { if (e.message.startsWith("no throw")) throw e; if (!(e instanceof RangeError)) throw new Error("wrong error type " + e.constructor.name); }
  // R6 SyntaxError cases
  for (const bad of ["v07-AB-012-G","V7-AB-012-G","V07-AB-12-G","V07-A-0122-G","V07--012-G","V07-AB-012-GG","V07-ab-012-G","V07-12-012-G","","V07-AB-012","V07-AB-012-G-x", 42, "V07-AB-012-g"])
    try { decodeTicket(bad); throw new Error("no throw for " + JSON.stringify(bad)); } catch (e) { if (e.message.startsWith("no throw")) throw e; if (!(e instanceof SyntaxError)) throw new Error("wrong error type " + JSON.stringify(bad) + " " + e.constructor.name); }
  // R6 RangeError cases
  for (const bad of ["V00-A-001-A","V01-A-000-A","V01-A-001-B","V07-AB-012-A"])
    try { decodeTicket(bad); throw new Error("no throw for " + bad); } catch (e) { if (e.message.startsWith("no throw")) throw e; if (!(e instanceof RangeError)) throw new Error("wrong error type " + bad + " " + e.constructor.name); }
  console.log("all sanity checks passed");
});'
